15	void ApplyWithSubqueryVisitor::visit(ASTPtr & ast, const Data & data)
16	{
17	    if (auto * node_select = ast->as<ASTSelectQuery>())
18	        visit(*node_select, data);
19	    else
20	    {
21	        for (auto & child : ast->children)
22	            visit(child, data);
23	        if (auto * node_func = ast->as<ASTFunction>())
24	            visit(*node_func, data);
25	        else if (auto * node_table = ast->as<ASTTableExpression>())
26	            visit(*node_table, data);
27	    }
28	}
