30	void ApplyWithSubqueryVisitor::visit(ASTSelectQuery & ast, const Data & data)
31	{
32	    std::optional<Data> new_data;
33	    if (auto with = ast.with())
34	    {
35	        for (auto & child : with->children)
36	        {
37	            visit(child, new_data ? *new_data : data);
38	            if (auto * ast_with_elem = child->as<ASTWithElement>())
39	            {
40	                if (!new_data)
41	                    new_data = data;
42	                new_data->subqueries[ast_with_elem->name] = ast_with_elem->subquery;
43	            }
44	        }
45	    }
46	
47	    for (auto & child : ast.children)
48	    {
49	        if (child != ast.with())
50	            visit(child, new_data ? *new_data : data);
51	    }
52	}
