60	void ApplyWithSubqueryVisitor::visit(ASTTableExpression & table, const Data & data)
61	{
62	    if (table.database_and_table_name)
63	    {
64	        auto table_id = table.database_and_table_name->as<ASTTableIdentifier>()->getTableId();
65	        if (table_id.database_name.empty())
66	        {
67	            auto subquery_it = data.subqueries.find(table_id.table_name);
68	            if (subquery_it != data.subqueries.end())
69	            {
70	                auto old_alias = table.database_and_table_name->tryGetAlias();
71	                table.children.clear();
72	                table.database_and_table_name.reset();
73	                table.subquery = subquery_it->second->clone();
74	                table.subquery->as<ASTSubquery &>().cte_name = table_id.table_name;
75	                if (!old_alias.empty())
76	                    table.subquery->setAlias(old_alias);
77	                table.children.emplace_back(table.subquery);
78	            }
79	        }
80	    }
81	}
