83	void ApplyWithSubqueryVisitor::visit(ASTFunction & func, const Data & data)
84	{
85	    /// Special CTE case, where the right argument of IN is alias (ASTIdentifier) from WITH clause.
86	
87	    if (checkFunctionIsInOrGlobalInOperator(func))
88	    {
89	        auto & ast = func.arguments->children.at(1);
90	        if (const auto * identifier = ast->as<ASTIdentifier>())
91	        {
92	            if (identifier->isShort())
93	            {
94	                /// Clang-tidy is wrong on this line, because `func.arguments->children.at(1)` gets replaced before last use of `name`.
95	                auto name = identifier->shortName();  // NOLINT
96	                auto subquery_it = data.subqueries.find(name);
97	                if (subquery_it != data.subqueries.end())
98	                {
99	                    auto old_alias = func.arguments->children[1]->tryGetAlias();
100	                    func.arguments->children[1] = subquery_it->second->clone();
101	                    func.arguments->children[1]->as<ASTSubquery &>().cte_name = name;
102	                    if (!old_alias.empty())
103	                        func.arguments->children[1]->setAlias(old_alias);
104	                }
105	            }
106	        }
107	    }
108	}
